        depth: u32,
        /// The configured maximum.
        max: u32,
    },

    /// A [`crate::SwarmAgent`] exceeded its configured handoff budget
    /// before any member produced a final output.
    #[error("max handoffs ({limit}) exceeded")]
    MaxHandoffsExceeded {
